/// <summary>
///    AVA <c>initValue</c> method.
/// </summary>
public void initValue()
{
    super();

    this.PriceIncreaseSet       = '';
    this.Description            = '';
    this.Status                 = AVAPriceIncreaseStatus::New;
    this.FromDate               = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    this.SalesEvaluationStart   = dateNull(); //dateMax();
}

/// <summary>
///    Finds the specified record in the <c>AVAPriceIncreaseTable</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>AVAPriceIncreaseTable</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceIncreaseTable</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceIncreaseTable find( AVAPriceIncreaseSet _recordId,
                                                boolean       _forUpdate = false)
{
    AVAPriceIncreaseTable record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        index hint PriceIncreaseSetIdx
        where   record.PriceIncreaseSet == _recordId;
    }
    return record;
}

/// <summary>
///    Finds the specified record in the <c>AVAPriceIncreaseTable</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>AVAPriceIncreaseTable</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceIncreaseTable</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceIncreaseTable findByRecId(RecId _recordId, boolean _forUpdate = false)
{
    AVAPriceIncreaseTable record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        where record.RecId == _recordId;
    }
    return record;
}

/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    switch(_fieldId)
    {
        case fieldNum(AVAPriceIncreaseTable, Status):
            if(this.Status == AVAPriceIncreaseStatus::New)
            {
                this.Status = AVAPriceIncreaseStatus::New;
            }
            break;

        default :
            break;
    }
    super(_fieldId);
}

/// <summary>
///    AVA <c>addMissingGoodsGroupLines</c> method.
/// </summary>
/// <param name="_avaPriceIncreaseSet">
///    <c>AVAPriceIncreaseSet</c> as type
/// </param>
/// <param name="_kcs_GoodsId">
///    <c>KCS_GoodsId</c> as type
/// </param>
/// <param name="_avaPriceIncreasePercentage">
///    <c>AVAPriceIncreasePercentage</c> as type
/// </param>
/// <param name="_checkOnly">
///    <c>boolean</c> as type
/// </param>
public static void addMissingGoodsGroupLines(   AVAPriceIncreaseSet         _avaPriceIncreaseSet,
                                                KCS_GoodsId                 _kcs_GoodsId                = '',       // all goods groups
                                                AVAPriceIncreasePercentage  _avaPriceIncreasePercentage = 0.0,
                                                boolean                     _checkOnly                  = false )   // info only
{
    AVAPriceIncreaseLine    locAVAPriceIncreaseLine;
    KCS_GoodsGroup          locKCS_GoodsGroup;
    KCS_GoodsId             locKCS_GoodsId;
    int                     locCounter;


    void insertAVAPriceIncreaseLine()
    {
        ttsbegin;
        locAVAPriceIncreaseLine.clear();
        locAVAPriceIncreaseLine.initValue();
        locAVAPriceIncreaseLine.PriceIncreaseSet        = _avaPriceIncreaseSet;
        locAVAPriceIncreaseLine.KCS_GoodsID             = locKCS_GoodsId;
        locAVAPriceIncreaseLine.PriceIncreasePercentage = _avaPriceIncreasePercentage;
        if (locAVAPriceIncreaseLine.validateWrite())
        {
            locAVAPriceIncreaseLine.write();
        }
        ttscommit;
    }

    setprefix(strfmt("@NDX:NXAMissingingGoodsGroupForPriceIncreaseSetP1", _avaPriceIncreaseSet));

    if(_avaPriceIncreaseSet)
    {
        if(_kcs_GoodsId)
        {
            locAVAPriceIncreaseLine =   AVAPriceIncreaseLine::find( _avaPriceIncreaseSet,
                                                                    _kcs_GoodsId            );
            if(!locAVAPriceIncreaseLine.RecId)
            {
                locKCS_GoodsId = _kcs_GoodsId;
                insertAVAPriceIncreaseLine();
            }
        }
        else
        {
            while select locKCS_GoodsGroup
            notexists join forUpdate  locAVAPriceIncreaseLine
                where   locAVAPriceIncreaseLine.PriceIncreaseSet    == _avaPriceIncreaseSet
                    &&  locAVAPriceIncreaseLine.KCS_GoodsID         == locKCS_GoodsGroup.KCS_GoodsId
            {
                locCounter++;
                info(strfmt('%1) %2', locCounter, locKCS_GoodsGroup.KCS_GoodsId));
                if (!_checkOnly)
                {
                    locKCS_GoodsId = locKCS_GoodsGroup.KCS_GoodsId;
                    insertAVAPriceIncreaseLine();
                }
            }
        }
    }

    if (!_checkOnly)
    {
        info(strfmt("@NDX:NXAP1GoodsGroupsAdded", locCounter));
    }
    else if (locCounter == 0)
    {
        info("@NDX:NXANoMissingGoodsGroupsFound");
    }
}

/// <summary>
///     AVA <c>getKCS_GoodsIdSetDefined</c> method.
/// </summary>
/// <returns>
///     <c>Set</c> as return value
/// </returns>
public Set getKCS_GoodsIdSetDefined(boolean _onlyZeroPercentage = false)
{
    Set                             locKCS_GoodsIdSetDefined;
    AVAPriceIncreaseLine            locAVAPriceIncreaseLine;

    locKCS_GoodsIdSetDefined = new Set(Types::String);

    if(_onlyZeroPercentage)
    {
        while select locAVAPriceIncreaseLine
        where   locAVAPriceIncreaseLine.PriceIncreaseSet        == this.PriceIncreaseSet
            &&  locAVAPriceIncreaseLine.PriceIncreasePercentage == 0
        {
            locKCS_GoodsIdSetDefined.add(locAVAPriceIncreaseLine.KCS_GoodsId);
        }
    }
    else
    {
        while select locAVAPriceIncreaseLine
        where   locAVAPriceIncreaseLine.PriceIncreaseSet        == this.PriceIncreaseSet
            &&  locAVAPriceIncreaseLine.PriceIncreasePercentage != 0
        {
            locKCS_GoodsIdSetDefined.add(locAVAPriceIncreaseLine.KCS_GoodsId);
        }
    }
    return locKCS_GoodsIdSetDefined;
}

/// <summary>
///     AVA <c>getPriceDiscGroupSetDefined</c> method.
/// </summary>
/// <returns>
///     <c>Set</c> as return value
/// </returns>
public Set getPriceDiscGroupSetDefined()
{
    Set                             locPriceDiscGroupSetDefined;
    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;

    locPriceDiscGroupSetDefined = new Set(Types::String);

    while select locAVAPriceIncreasePriceDiscGroup
    where   locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet == this.PriceIncreaseSet
    {
        locPriceDiscGroupSetDefined.add(locAVAPriceIncreasePriceDiscGroup.GroupId);
    }
    return locPriceDiscGroupSetDefined;
}
